import { createHash } from 'node:crypto'

/** Match the public opaque ID generated by the calendar normalization boundary. */
export const calendarPublicId = (providerId: string): string =>
  createHash('sha256').update(providerId).digest('hex').slice(0, 24)

export const qaEventIds = {
  chicago: calendarPublicId('qa-chicago-event-2027'),
  austin: calendarPublicId('qa-austin-event-2027'),
  cancelled: calendarPublicId('qa-cancelled-event-2027'),
  allDay: calendarPublicId('qa-all-day-event-2027'),
  ended: calendarPublicId('qa-ended-event-2025'),
} as const

export const calendarClientFixtureIds = {
  chicago: calendarPublicId('event-chicago'),
  austin: calendarPublicId('event-austin'),
  newYork: calendarPublicId('event-new-york'),
  losAngeles: calendarPublicId('event-los-angeles'),
  cancelled: calendarPublicId('event-cancelled'),
  allDay: calendarPublicId('event-all-day'),
} as const
